import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"In-House Development and Integration Boundaries","description":"Hearth's boundaries between the in-house core, adapter layer, direct integrations, and learn-only-without-integration; and the Codex integration approach.","frontmatter":{"title":"In-House Development and Integration Boundaries","description":"Hearth's boundaries between the in-house core, adapter layer, direct integrations, and learn-only-without-integration; and the Codex integration approach.","outline":[2,3]},"headers":[],"relativePath":"en/reference/build-vs-integrate.md","filePath":"en/reference/build-vs-integrate.md","lastUpdated":null}`),i={name:"en/reference/build-vs-integrate.md"};function r(s,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<p class="eyebrow">BUILD VS. INTEGRATE</p><h1 id="build-vs-integrate-boundary" tabindex="-1">Build vs. Integrate Boundary <a class="header-anchor" href="#build-vs-integrate-boundary" aria-label="Permalink to &quot;Build vs. Integrate Boundary&quot;">​</a></h1><p class="lead">Hearth builds the core control and memory itself, and directly integrates models, Codex, browsers, document parsing, and Sandbox kernels. The clearer the boundary, the less likely the product is to turn into an integration grab bag.</p><h2 id="one-sentence-summary" tabindex="-1">One-Sentence Summary <a class="header-anchor" href="#one-sentence-summary" aria-label="Permalink to &quot;One-Sentence Summary&quot;">​</a></h2><p>Hearth builds the “command system, ledger, gates, and acceptance” itself, and integrates “models, sandboxes, browsers, document parsers, and external APIs.”</p><p>Here, “build” mainly means building the product and core logic in-house, not writing every underlying library from scratch. For example, the Event Log protocol is built in-house, but the underlying database is SQLite; the frontend experience is built in-house, but uses React/Vite.</p><h2 id="delivery-boundary-building-the-core-does-not-mean-doing-it-last" tabindex="-1">Delivery Boundary: Building the Core Does Not Mean Doing It Last <a class="header-anchor" href="#delivery-boundary-building-the-core-does-not-mean-doing-it-last" aria-label="Permalink to &quot;Delivery Boundary: Building the Core Does Not Mean Doing It Last&quot;">​</a></h2><p>“Build” describes ownership of responsibility, not development order. Hearth will not first finish the Control Plane, Harness, Memory, and all Executors, and only then add the frontend.</p><ul><li><strong>The frontend is part of the core build</strong>: task cards, approvals, artifacts, recovery, and mobile entry points are the visible parts of product differentiation, not a wrapper layer added after the backend is complete.</li><li><strong>A prototype exists at Stage 0</strong>: use a clickable Web prototype to validate the product narrative, states, and primary actions, even if the data is simulated.</li><li><strong>Deliver an MVP early at Stage 1</strong>: on a narrow task family, simultaneously deliver a real Web app, durable state, Codex execution, artifacts, approval drills, and failure recovery.</li><li><strong>Every increment is a vertical slice</strong>: user outcomes, interface, backend, Executor, validation, and recovery appear together; a capability that exists only as a CLI or log does not count as completing a stage.</li><li><strong>The build/integrate boundary does not change because of the MVP</strong>: the MVP still does not build models, container kernels, or a complete Agent framework in-house, but it must build task control, validation, approval, recovery, and the user interface in-house.</li></ul><p>For the specific increment order, see Chapter 25 of the main roadmap or the volume <code>Hearth_路线图分册/09_从0到100开发计划.md</code>.</p><h2 id="_1-core-parts-hearth-builds-itself" tabindex="-1">1. Core Parts Hearth Builds Itself <a class="header-anchor" href="#_1-core-parts-hearth-builds-itself" aria-label="Permalink to &quot;1. Core Parts Hearth Builds Itself&quot;">​</a></h2><p>These are the product moats identified in the document and cannot be outsourced:</p><ul><li><p><strong>Control Plane</strong><br> Decides whether an event should be processed, whether to create a Task, whether execution is allowed, which Executor to use, how much budget to spend, when to ask you for approval, and whether to retry or hand off to a human after failure.</p></li><li><p><strong>Durable Harness</strong><br> Task, Ticket, Run, task graph, dependencies, lease, single writer, fencing token, checkpoints, retries, cancellation, and crash recovery.</p></li><li><p><strong>Event Log and projections</strong><br> Append-only source of truth, schema, migration, task state projections, auditing, and replay. What is built in-house here is the protocol and semantics, not the database engine.</p></li><li><p><strong>Policy, Mandate, Capability, Approval</strong><br> Long-term rules, one-time authorization, resource scope and duration, risk classification, approval binding, and permission revocation.</p></li><li><p><strong>External side-effect control</strong><br> Effect Preview, outbox, idempotency keys, Effect Dispatcher, Receipt, reconciliation, and dead-letter handling. This is the core of “never send the same email twice and never make the same payment twice.”</p></li><li><p><strong>Context Compiler and Token Governor</strong><br> Assemble the minimal Task Pack, select the model ladder, control context, caching, budget, cost attribution, and abnormal termination.</p></li><li><p><strong>Memory OS</strong><br> Five types of memory, provenance and trustworthiness, conflicts, sensitivity, recall, forgetting, multi-device sync, and memory UI.</p></li><li><p><strong>Evolution OS</strong><br> Trajectory mining, skill candidates, evaluation sets, Shadow, Canary, promotion, permission checks, and rollback.</p></li><li><p><strong>Control logic of the Execution Gateway</strong><br> Workspace lifecycle, mounts and file permissions, network allowlists and egress, Capability, quotas, snapshots, recovery, auditing, and takeover.</p></li><li><p><strong>Credential Broker</strong><br> Long-term secret storage, short-lived credential issuance, scoping by task and account, usage auditing, and revocation, ensuring models cannot see the original password or refresh token.</p></li><li><p><strong>Personal Gateway and experience layer</strong><br> Channel event normalization, deduplication, device registration, capability catalog, attention inbox, task cards, approval UI, artifact center, mobile entry point, and takeover flow.</p></li><li><p><strong>Validators and evaluation system</strong><br> Tests, diff, citation checks, table checks, email recipient checks, web page status checks, fault injection, and trajectory replay.</p></li><li><p><strong>Thin execution layer of the Native Runtime</strong><br> Short-task tool loop, session tree, steering, compaction, and logic for escalation to Codex; the model itself is not built in-house.</p></li></ul><h2 id="_2-hearth-builds-the-adapter-layer-in-house-but-uses-off-the-shelf-capabilities-underneath" tabindex="-1">2. Hearth Builds the “Adapter Layer” In-House but Uses Off-the-Shelf Capabilities Underneath <a class="header-anchor" href="#_2-hearth-builds-the-adapter-layer-in-house-but-uses-off-the-shelf-capabilities-underneath" aria-label="Permalink to &quot;2. Hearth Builds the “Adapter Layer” In-House but Uses Off-the-Shelf Capabilities Underneath&quot;">​</a></h2><p>This category is not fully built in-house, nor is it a simple API call; instead, Hearth controls the interface, policy, validation, and recovery:</p><ul><li><p><strong>Codex Executor</strong><br> Integrates Codex, but Hearth handles version pinning, Task Pack, workspace isolation, structured output, timeout cancellation, validation, and failure classification.</p></li><li><p><strong>Browser Executor</strong><br> Uses Playwright for the browser engine and automation; Hearth handles login-state boundaries, web policy, prompt injection protection, validation, screenshots, and human takeover.</p></li><li><p><strong>Connector Executor</strong><br> Email, calendar, cloud drive, IM, and similar services connect through official APIs or MCP; Hearth handles the unified <code>Source/Effect</code> protocol, permissions, rate limiting, idempotency, receipts, and reconciliation.</p></li><li><p><strong>Document/Data Executor</strong><br> Uses mature Python libraries for parsing, OCR, format conversion, and spreadsheet processing; Hearth handles pipeline scheduling, minimal context extraction, result validation, and division of labor with Codex.</p></li><li><p><strong>Sandbox</strong><br> Uses Docker, OCI containers, or microVMs; Hearth handles the Sandbox Provider interface, workspace lifecycle, network allowlists, credential isolation, and reclamation.</p></li><li><p><strong>GUI Executor</strong><br> Uses the accessibility tree, screenshots, keyboard/mouse, and window capabilities provided by the operating system; Hearth handles agentd, task boundaries, validation, recovery, and human takeover.</p></li><li><p><strong>Observability</strong><br> Uses OpenTelemetry; Hearth handles task trajectory semantics, Token attribution, and user-visible audit views.</p></li></ul><h2 id="_3-parts-explicitly-integrated-directly-from-others" tabindex="-1">3. Parts Explicitly Integrated Directly from Others <a class="header-anchor" href="#_3-parts-explicitly-integrated-directly-from-others" aria-label="Permalink to &quot;3. Parts Explicitly Integrated Directly from Others&quot;">​</a></h2><p>The document explicitly does not rewrite these mature infrastructure components:</p><ul><li><strong>Models</strong>: OpenAI, Anthropic, local models, or other model APIs, using BYOM; no training of foundation models and no in-house inference engine.</li><li><strong>Codex</strong>: currently the only integrated external Agent, capable of handling code, research, documents, spreadsheets, and complex workspace tasks.</li><li><strong>Playwright</strong>: browser automation engine.</li><li><strong>Document parsing and conversion libraries</strong>: PDF, Office, OCR, spreadsheet processing, etc.</li><li><strong>Official APIs or MCP for email, calendar, cloud drive, etc.</strong>: connections to real external systems.</li><li><strong>Container/microVM/Sandbox kernels</strong>: start with Docker; use stronger isolation for high-risk tasks.</li><li><strong>OpenTelemetry</strong>: observability infrastructure.</li><li><strong>Standard technology stack</strong>: TypeScript, Node.js, SQLite, React, Vite, Fastify/Hono, Zod, Python sidecar, etc.</li></ul><h2 id="_4-projects-to-learn-from-only-without-integrating-or-using-as-a-product-foundation" tabindex="-1">4. Projects to Learn From Only, Without Integrating or Using as a Product Foundation <a class="header-anchor" href="#_4-projects-to-learn-from-only-without-integrating-or-using-as-a-product-foundation" aria-label="Permalink to &quot;4. Projects to Learn From Only, Without Integrating or Using as a Product Foundation&quot;">​</a></h2><p>This boundary is very important:</p><ul><li><strong>OpenClaw</strong>: learn from its Gateway, channels, device nodes, attention entry points, and always-on mode; do not fork it or use it as a runtime dependency.</li><li><strong>Hermes</strong>: learn from its memory budget, memory constraints, skill consolidation, and evolution loop; do not adopt unbounded self-modification.</li><li><strong>DeerFlow</strong>: learn from its Harness/App layering, Run lifecycle, and thread isolation; do not introduce heavy framework coupling.</li><li><strong>Pi / Maka</strong>: learn from session tree, steering, compaction, and Event Log; do not copy the complete framework.</li><li><strong>OpenSandbox / OpenBot</strong>: learn from isolation, snapshots, takeover, and receipt; do not copy the complete product.</li><li><strong>OpenMuse / OpenDots</strong>: learn from durable jobs, checkpoints, leases, and low-interruption experience.</li><li><strong>Codex</strong>: a special case—learn from its workspace execution model and also actually integrate it.</li></ul><p>Therefore, in the current document:</p><blockquote><p>Hearth does not integrate OpenClaw, Hermes, or DeerFlow at runtime, nor does it treat them as a product foundation. The only external Agent currently integrated is Codex; other projects are mainly reference patterns and learning targets.</p></blockquote><h2 id="remember-the-boundary-in-one-sentence" tabindex="-1">Remember the boundary in one sentence <a class="header-anchor" href="#remember-the-boundary-in-one-sentence" aria-label="Permalink to &quot;Remember the boundary in one sentence&quot;">​</a></h2><blockquote><p>What Hearth builds itself is “how tasks are authorized, scheduled, verified, recovered, and remembered”; what it integrates is “the mature engines and tools needed to complete tasks.”</p></blockquote><p>It does not want to reinvent models, containers, browsers, or document parsers; instead, it wants to organize them into a controllable, auditable, and recoverable personal Agent OS.</p><h2 id="sources-in-the-original-text" tabindex="-1">Sources in the original text <a class="header-anchor" href="#sources-in-the-original-text" aria-label="Permalink to &quot;Sources in the original text&quot;">​</a></h2><ul><li>Build vs Integrate: <code>Hearth_个人Agent_OS_总体路线图_v3.md:280</code></li><li>Sandbox boundary: <code>:2019</code></li><li>Recommended tech stack: <code>:3848</code></li><li>Final judgment: <code>:4256</code></li></ul><hr><h2 id="v-the-real-differences-between-hearth-and-openclaw" tabindex="-1">V. The Real Differences Between Hearth and OpenClaw <a class="header-anchor" href="#v-the-real-differences-between-hearth-and-openclaw" aria-label="Permalink to &quot;V. The Real Differences Between Hearth and OpenClaw&quot;">​</a></h2><h3 id="conclusion-first" tabindex="-1">Conclusion first <a class="header-anchor" href="#conclusion-first" aria-label="Permalink to &quot;Conclusion first&quot;">​</a></h3><p><strong>In terms of product capabilities that can be used directly today, OpenClaw is clearly ahead of Hearth; Hearth is still a roadmap, not a delivered system.</strong></p><p>Therefore, one cannot say “Hearth is already stronger than OpenClaw,” nor can one say “Hearth is naturally a layer above OpenClaw.” A more accurate statement is:</p><blockquote><p><strong>OpenClaw is already a mature personal assistant Gateway and Control Plane; Hearth aims to build a stricter task control layer centered on “tasks and commitments” as core objects.</strong></p></blockquote><p>The difference between the two is not “whose feature list is longer,” but “who is responsible for what”:</p><ul><li>OpenClaw is primarily responsible for <strong>sessions, channels, personal assistant experience, and always-on services</strong>;</li><li>Hearth primarily aims to be responsible for <strong>whether tasks are correctly authorized, whether they are actually completed, whether external side effects are provable, and whether recovery is possible after failure</strong>.</li></ul><p>These two directions overlap heavily. OpenClaw already has memory, audit, approvals, sandboxing, queues, restart recovery, and multi-device entry points, so these capabilities can no longer be described as unique to Hearth.</p><h3 id="where-exactly-do-they-differ" tabindex="-1">Where exactly do they differ <a class="header-anchor" href="#where-exactly-do-they-differ" aria-label="Permalink to &quot;Where exactly do they differ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dimension</th><th>OpenClaw</th><th>Hearth&#39;s design goal</th></tr></thead><tbody><tr><td>Core object</td><td>Sessions, channel messages, Agent Run, always-on personal assistant</td><td>Event → Task → Ticket → Run; tasks and commitments are first-class objects</td></tr><tr><td>Product focus</td><td>Provides an always-available personal assistant within the user&#39;s existing chat channels</td><td>Manages long-running tasks, cross-Executor collaboration, authorization, budgets, and acceptance</td></tr><tr><td>Interaction model</td><td>Chat, channel messages, Control UI, mobile and desktop nodes</td><td>Task cards, approvals, Artifact center, inbox, and mobile takeover</td></tr><tr><td>Memory</td><td>Has implemented layered memory, provenance tracking, trust boundaries, Dreaming, user models, and standing intents</td><td>Plans to build a Memory OS with provenance, conflicts, sensitivity, forgetting, and multi-device sync; functionally it overlaps significantly with OpenClaw</td></tr><tr><td>Audit</td><td>Has implemented a bounded, metadata-level audit ledger, execution identities, approval decision records, and message lifecycle auditing; its documentation explicitly states that the ledger is neither a lossless record nor authorization evidence</td><td>Plans to use the Event Log as the source of truth and bind Effects, approvals, execution, and acceptance to the same task trajectory</td></tr><tr><td>External side effects</td><td>Requires idempotency keys for side-effecting calls such as <code>send</code> and <code>agent</code>, and has message delivery auditing</td><td>Further models external side effects as typed Effects, reconciled through outbox, idempotency keys, Dispatcher, and Receipt</td></tr><tr><td>Completion determination</td><td>Has Run status, audit, and results; but “whether the task is actually complete” still mainly depends on the execution flow and higher-level judgment</td><td>Plans to make Verifier the completion gate; it cannot simply trust the Executor saying “completed”</td></tr><tr><td>Sandbox</td><td>Has implemented backends such as Docker, Podman, SSH, OpenShell, and Crabbox</td><td>Plans to build only the Sandbox Provider interface, lifecycle, network egress, and credential isolation itself, reusing mature sandboxes underneath</td></tr><tr><td>Recovery</td><td>Already has queues, session controller, watchdog, restart recovery, and automatic resumption</td><td>Plans to use Event Log, lease, fencing, checkpoint, retry, and human takeover for task-level recovery</td></tr><tr><td>Ecosystem and channels</td><td>20+ chat channels, desktop/mobile nodes, plugins, skills, and ClawHub</td><td>The current roadmap only has a mobile-first PWA and has not yet formed a channel and plugin ecosystem</td></tr><tr><td>Maturity</td><td>Has runnable code, documentation, installers, tests, and real usage paths</td><td>Is still an architecture and implementation roadmap, with no comparable evidence of a runnable product</td></tr></tbody></table><h3 id="why-is-it-easy-to-mistakenly-think-hearth-is-a-layer-above" tabindex="-1">Why is it easy to mistakenly think Hearth is “a layer above” <a class="header-anchor" href="#why-is-it-easy-to-mistakenly-think-hearth-is-a-layer-above" aria-label="Permalink to &quot;Why is it easy to mistakenly think Hearth is “a layer above”&quot;">​</a></h3><p>Because both are doing “control,” but they control different objects:</p><ul><li>OpenClaw&#39;s Control Plane mainly controls <strong>Gateway, sessions, channels, execution identities, and message delivery</strong>;</li><li>Hearth aims to control <strong>task contracts, authorization scope, context budgets, external side effects, and acceptance results</strong>.</li></ul><p>If in the future Hearth integrates OpenClaw as a Gateway or Executor, then the relationship could look like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hearth: Task, Mandate, budget, acceptance, side-effect Receipt</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>OpenClaw: channels, sessions, personal assistant runtime, device nodes</span></span>
<span class="line"><span>                 ↓</span></span>
<span class="line"><span>Codex / other Executors: actually complete a given piece of work</span></span></code></pre></div><p>Under this specific architecture, Hearth is the &quot;task control layer,&quot; and OpenClaw is the personal assistant runtime beneath it. But note the following:</p><ol><li>This is not what the current roadmap implements;</li><li>The current roadmap only integrates Codex and does not treat OpenClaw as a runtime component;</li><li>OpenClaw itself can already integrate with Codex and various other Agent Harnesses, so &quot;integrating Codex&quot; does not automatically make Hearth a layer above OpenClaw;</li><li>The upper/lower-layer relationship only holds when Hearth genuinely owns task authorization, budgets, side effects, and acceptance, and OpenClaw is responsible only for channels and execution.</li></ol><p>Therefore, &quot;a control plane one layer above&quot; should be revised to:</p><blockquote><p><strong>Hearth aims to be the control plane for the task and commitment layer, not a product that is inherently superior to OpenClaw. It must earn its place as a layer above OpenClaw through explicit interfaces, permissions, and receipt boundaries.</strong></p></blockquote><h3 id="under-what-conditions-is-hearth-genuinely-stronger" tabindex="-1">Under what conditions is Hearth genuinely stronger <a class="header-anchor" href="#under-what-conditions-is-hearth-genuinely-stronger" aria-label="Permalink to &quot;Under what conditions is Hearth genuinely stronger&quot;">​</a></h3><p>Strength cannot be proven by &quot;having more features,&quot; only by verifiable differences. It must pass at least the following four categories of tests:</p><ol><li><strong>Side-effect test</strong>: When a task crashes midway, is retried, or is restarted, emails are not sent twice, orders are not submitted twice, files are not overwritten twice, and reconciliation can be performed using Receipts.</li><li><strong>Completion test</strong>: After an executor claims completion, Hearth can prove through tests, diffs, citations, file structure, web page state, or business rules that the result truly satisfies the task definition.</li><li><strong>Permission test</strong>: When an executor is subjected to prompt injection or attempts privilege escalation, it cannot obtain credentials, directories, network access, or tools beyond the Task Mandate.</li><li><strong>Cost test</strong>: On the same task set, Hearth&#39;s Token, latency, and human-attention costs are no higher than using OpenClaw directly or Codex directly, and there is explainable attribution.</li></ol><p>If these four things are not achieved, Hearth is just a later, more complex OpenClaw; if they are achieved, only then does it have the right to claim it is stronger at the &quot;task reliability&quot; layer.</p><h2 id="vi-can-codex-really-be-integrated-and-can-all-of-its-capabilities-be-used" tabindex="-1">VI. Can Codex really be integrated, and can all of its capabilities be used <a class="header-anchor" href="#vi-can-codex-really-be-integrated-and-can-all-of-its-capabilities-be-used" aria-label="Permalink to &quot;VI. Can Codex really be integrated, and can all of its capabilities be used&quot;">​</a></h2><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p><strong>Technically it can be integrated, and it is feasible for the roadmap to use Codex as the first external Executor.</strong></p><p><strong>But you cannot say &quot;all of Codex&#39;s capabilities can be used.&quot;</strong> You can only use the subset of capabilities that Codex publicly exposes, that the current account and version permit, and whose interfaces are relatively stable.</p><p>Codex is an executor, not Hearth&#39;s permission center, task database, memory center, or external side-effect gateway.</p><h3 id="confirmed-integration-entry-points" tabindex="-1">Confirmed integration entry points <a class="header-anchor" href="#confirmed-integration-entry-points" aria-label="Permalink to &quot;Confirmed integration entry points&quot;">​</a></h3><p>Based on local <code>codex-cli 0.163.0</code> and <code>@openai/codex-sdk 0.166.0</code> as the verification baseline:</p><ul><li><strong><code>codex exec</code></strong>: non-interactive execution, suitable for Hearth&#39;s first-phase integration. <ul><li><code>--json</code>: outputs a JSONL event stream;</li><li><code>--output-schema</code>: constrains the final structured output;</li><li><code>-C</code>: specifies the working directory;</li><li><code>--sandbox read-only | workspace-write | danger-full-access</code>: sandbox mode;</li><li><code>-a / --ask-for-approval</code>: global approval policy, which must be placed before <code>exec</code>; the <code>codex exec</code> subcommand itself does not accept this parameter;</li><li><code>--ephemeral</code>: does not persist session files;</li><li><code>--skip-git-repo-check</code>: allows non-Git directories;</li><li><code>--add-dir</code>: adds a writable directory;</li><li><code>-i</code>: attaches images;</li><li><code>-o</code>: writes the last message to a file;</li><li><code>resume</code>, <code>fork</code>, <code>review</code>: resume, fork, and code review.</li></ul></li><li><strong><code>@openai/codex-sdk</code></strong>: TypeScript SDK, essentially launching the Codex CLI and exchanging JSONL over stdin/stdout. <ul><li><code>startThread()</code> / <code>resumeThread()</code>;</li><li><code>run()</code> / <code>runStreamed()</code>;</li><li>structured output, image input, working directory, sandbox mode, approval policy, model, and reasoning effort;</li><li>command execution, file modification, MCP tool calls, web search, todo, and usage events.</li></ul></li><li><strong><code>codex app-server</code></strong>: experimental interface supporting stdio, Unix socket, and WebSocket, capable of generating TypeScript bindings and JSON Schema. Suitable for deep integration requiring fine-grained streaming events and approvals, but it must be treated as an experimental interface.</li><li><strong><code>codex exec-server</code></strong>: experimental standalone remote execution service.</li><li><strong><code>codex cloud</code></strong>: experimental Codex Cloud task interface, dependent on account and Cloud capabilities.</li><li><strong>MCP / plugins</strong>: external tools and plugins can be managed via <code>codex mcp</code> and <code>codex plugin</code>.</li></ul><h3 id="why-you-cannot-say-all-capabilities" tabindex="-1">Why you cannot say &quot;all capabilities&quot; <a class="header-anchor" href="#why-you-cannot-say-all-capabilities" aria-label="Permalink to &quot;Why you cannot say &quot;all capabilities&quot;&quot;">​</a></h3><p>The following limitations are structural, not laziness at the integration layer:</p><ol><li><strong>Account and plan limitations</strong>: models, Cloud, Web Search, organizational policies, and regional availability are all constrained by the OpenAI account and permissions.</li><li><strong>Version limitations</strong>: the protocols of the CLI, SDK, and app-server may change; the local CLI and SDK versions are already inconsistent, and you cannot assume that arbitrary versions are compatible with each other.</li><li><strong>Experimental interface limitations</strong>: <code>app-server</code>, <code>exec-server</code>, and <code>cloud</code> are all explicitly marked experimental and are not guaranteed to be stable.</li><li><strong>The SDK is not the full platform</strong>: the SDK is a wrapper layer over the CLI and does not cover the Codex desktop app, account management, billing management, or all Cloud/UI capabilities.</li><li><strong>Codex does not provide Hearth&#39;s governance capabilities</strong>: Mandate, Capability, Credential Broker, Effect outbox, idempotent delivery, Receipt reconciliation, and Verifier are all outside Codex.</li><li><strong>Session persistence is not a task event log</strong>: Codex&#39;s thread/session can be resumed, but it cannot replace Hearth&#39;s source of truth, task graph, or audit semantics.</li><li><strong>MCP tools are not safe tools</strong>: just because Codex can call MCP does not mean high-risk tools such as email, calendar, and payments should be handed to it directly.</li><li><strong><code>danger-full-access</code> is not the default option</strong>: it may only be used in disposable, strongly isolated, destroyable sandboxes; normal tasks should use the minimum directory and minimum network permissions.</li></ol><h3 id="recommended-integration-architecture" tabindex="-1">Recommended integration architecture <a class="header-anchor" href="#recommended-integration-architecture" aria-label="Permalink to &quot;Recommended integration architecture&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hearth Task / Ticket</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Context Compiler generates the minimal Task Pack</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Codex Adapter: version check, workspace preparation, permission injection, timeout control</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>codex exec --json --output-schema in an isolated Workspace</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>JSONL events + structured results + artifact manifest</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Hearth Verifier: tests, diff, references, file checks, business rules</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Accept / retry / roll back / manual takeover</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>When external side effects are required, Hearth Connector handles them via outbox, idempotency keys, and Receipt</span></span></code></pre></div><p>The key point is: <strong>Codex can write files, run commands, and invoke controlled tools inside the sandbox; however, external side effects such as sending email, modifying calendars, making payments, and publishing must go back through Hearth&#39;s Effect channel and cannot be performed directly by Codex.</strong></p><h3 id="recommended-three-phase-implementation" tabindex="-1">Recommended three-phase implementation <a class="header-anchor" href="#recommended-three-phase-implementation" aria-label="Permalink to &quot;Recommended three-phase implementation&quot;">​</a></h3><p><strong>Phase 1: Get a single task working end to end</strong></p><ul><li>Use <code>codex exec --json --output-schema</code>;</li><li>Use a separate temporary workspace for each Run;</li><li>Mount only the directories the task needs;</li><li>Configure timeouts, cancellation, and process-tree cleanup;</li><li>Parse JSONL and persist events, usage, and the final structured result;</li><li>Use Hearth&#39;s own Verifier to determine success.</li></ul><p><strong>Phase 2: Add multi-turn and recovery</strong></p><ul><li>Persist the Codex thread id, but treat the Hearth Event Log as the authoritative state;</li><li>Use <code>resume</code> when multiple turns are needed;</li><li>After a task fails, first classify it: model failure, tool failure, verification failure, permission failure, or environment failure;</li><li>Use idempotency keys for retryable tasks to avoid duplicate side effects.</li></ul><p><strong>Phase 3: Re-evaluate app-server</strong></p><ul><li>Introduce <code>app-server</code> only when fine-grained streaming events, native approval forwarding, or long-lived connections are truly required;</li><li>Pin the CLI and protocol versions;</li><li>Establish contract tests for protocol generation and event fields;</li><li>Maintain forward compatibility with unknown events; do not crash because of newly added fields.</li></ul><h3 id="hard-rules-for-integrating-codex" tabindex="-1">Hard rules for integrating Codex <a class="header-anchor" href="#hard-rules-for-integrating-codex" aria-label="Permalink to &quot;Hard rules for integrating Codex&quot;">​</a></h3><ul><li><strong>Pin versions</strong>: Record the CLI version, SDK version, and protocol version, and run contract tests before upgrading;</li><li><strong>Minimal workspace</strong>: One workspace per Run, reclaimed when the task ends;</li><li><strong>Minimal environment variables</strong>: Do not pass long-lived keys, browser cookies, or unrelated credentials to child processes;</li><li><strong>Minimal network egress</strong>: Disabled by default or allowlisted, permitting only the domains the task needs;</li><li><strong>Structured output</strong>: Require <code>--output-schema</code>; do not parse natural language to determine success;</li><li><strong>Independent verification</strong>: Codex saying it is done does not count as done; it must pass the Hearth Verifier;</li><li><strong>Side-effect isolation</strong>: Codex does not directly hold permissions for email, calendars, payments, or publishing;</li><li><strong>Cancellable</strong>: Timeouts and user cancellation must terminate the entire process tree, not merely stop reading output;</li><li><strong>Log redaction</strong>: JSONL, command output, and error messages may contain sensitive data and must be redacted before being written to the Event Log;</li><li><strong>Prefer ephemeral sessions</strong>: Use <code>--ephemeral</code> for one-off tasks; explicitly persist the thread id only when recovery is needed.</li></ul><h3 id="final-judgment" tabindex="-1">Final judgment <a class="header-anchor" href="#final-judgment" aria-label="Permalink to &quot;Final judgment&quot;">​</a></h3><p>Codex can serve as Hearth&#39;s “high-capability workspace executor,” and Phase 1 integration can be done now. But the correct goal is not to “embed all of Codex&#39;s capabilities”; rather, it is:</p><blockquote><p><strong>Define a subset of Codex capabilities for which Hearth itself can verify results, enforce permissions, handle recovery, and perform billing, and encapsulate it as a stable Executor contract.</strong></p></blockquote><p>This is also the dividing line between Hearth and a “Codex wrapper”: a wrapper treats Codex as the product; Hearth treats Codex as a replaceable, governable execution engine.</p><h2 id="additional-references" tabindex="-1">Additional references <a class="header-anchor" href="#additional-references" aria-label="Permalink to &quot;Additional references&quot;">​</a></h2><ul><li>Hearth&#39;s Codex positioning and Build vs Integrate: <code>Hearth_个人Agent_OS_总体路线图_v3.md</code>, sections 2.3–2.4</li><li>Hearth&#39;s final integration boundary: <code>Hearth_个人Agent_OS_总体路线图_v3.md</code>, section 29.5</li><li>MVP and the 0-to-100 development sequence: <code>Hearth_个人Agent_OS_总体路线图_v3.md</code>, chapter 25</li><li>OpenClaw Gateway, channels, and device nodes: local OpenClaw documentation <code>docs/concepts/architecture.md</code></li><li>OpenClaw audit ledger and execution identity: local OpenClaw documentation <code>docs/gateway/audit.md</code></li><li>OpenClaw sandbox backends: local OpenClaw documentation <code>docs/gateway/sandboxing.md</code></li><li>OpenClaw memory architecture: local OpenClaw documentation <code>docs/concepts/memory-architecture.md</code></li><li>OpenClaw queues and recovery: local OpenClaw documentation <code>docs/concepts/queue.md</code>, <code>docs/gateway/restart-recovery.md</code></li><li>OpenClaw standing intents: local OpenClaw documentation <code>docs/concepts/standing-intents.md</code></li><li>Codex CLI capabilities: <code>codex exec --help</code>, <code>codex app-server --help</code>, <code>codex exec-server --help</code>, and <code>codex cloud --help</code> for local <code>codex-cli 0.163.0</code></li><li>Codex SDK capabilities: <code>README.md</code> and <code>dist/index.d.ts</code> for <code>@openai/codex-sdk 0.166.0</code></li></ul><blockquote><p>Note: OpenClaw capabilities are based on verification against local documentation and source code; Codex capabilities are based on the local CLI and npm SDK versions. Both may continue to evolve, so version and interface verification must be repeated before formal integration.</p></blockquote>`,83)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
